mapper.select:
SELECT user_id, login_id, user_name, dept_name, phone, email, use_yn, reg_dt, upd_dt FROM base_user
AND (login_id LIKE CONCAT('%', #{keyword}, '%') OR user_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY user_id DESC LIMIT #{size} OFFSET #{offset}

SELECT user_id, login_id, password, user_name, dept_name, phone, email, use_yn, reg_dt, upd_dt
FROM base_user
WHERE user_id = #{userId}

SELECT user_id, login_id, password, user_name, dept_name, phone, email, use_yn, reg_dt, upd_dt
FROM base_user
WHERE login_id = #{loginId}

mapper.update:
UPDATE base_user SET user_name = #{userName}, dept_name = #{deptName}, phone = #{phone}, email = #{email}, use_yn = #{useYn}, upd_dt = NOW()
, password = #{password}
WHERE user_id = #{userId}
